exercice.solution:
class Inventaire:
    def __init__(self):
        self.stock = {}

    def ajouter(self, produit, quantite, prix):
        if produit in self.stock:
            self.stock[produit]["quantite"] += quantite
        else:
            self.stock[produit] = {"quantite": quantite, "prix": prix}
        self.stock[produit]["prix"] = prix

    def valeur_totale(self):
        return round(sum(p["quantite"] * p["prix"] for p in self.stock.values()), 2)

    def plus_precieux(self, n):
        valeur = lambda nom: self.stock[nom]["quantite"] * self.stock[nom]["prix"]
        return sorted(self.stock, key=valeur, reverse=True)[:n]
